"""Presentation of backend research diagnostics; no frontend inference logic."""
PANEL='''<section class="panel" id="c9-study" style="margin-top:24px"><h2>Cycle 9 research diagnostics</h2><p>Compare complete and in-board candidate sets, inspect failure provenance, and export empirical calibration results. Calibrated estimates are separate from native PLN strength and confidence.</p><div class="summary"><button type="button" id="c9-load">Load cohort metrics</button><button type="button" id="c9-calibration">Calibration report</button><button type="button" id="c9-failures">Failure families</button><button type="button" id="c9-performance">Performance diagnostics</button><button type="button" id="c9-identity">Runtime and model identity</button><button type="button" id="c9-export">Export research JSON</button></div><p id="c9-status" role="status" style="overflow-wrap:anywhere">No research report loaded.</p><label for="c9-population">Candidate population</label><select id="c9-population"><option value="complete">Complete candidate set</option><option value="in_board">In-board candidates only</option></select><div style="overflow-x:auto;max-width:100%"><table id="c9-table" style="width:100%;min-width:600px;text-align:left"><thead><tr><th>Mode / cohort</th><th>Candidates</th><th>Precision</th><th>Recall</th><th>Exact sets</th><th>False legal</th><th>False illegal</th><th>Unknown</th></tr></thead><tbody></tbody></table></div><label for="c9-case">Recorded failure and proof</label><select id="c9-case" disabled><option>Load failure families first</option></select><div class="summary"><button type="button" id="c9-proof" disabled>View recorded native trace</button><button type="button" id="c9-use" disabled>Inspect this position</button></div><pre id="c9-detail"></pre></section>'''
LIVE='''<details open><summary>Empirical estimate and model identity</summary><p>Empirical estimates are diagnostics, not native PLN truth values or complete legality proofs.</p><pre id="c9-live"></pre></details>'''
SCRIPT=r'''
let c9Current=null,c9Metrics=null,c9Failure=null;
const c9Pct=x=>x===null||x===undefined?'—':(100*x).toFixed(2)+'%';
function c9Render(){const body=document.querySelector('#c9-table tbody');body.replaceChildren();if(!c9Metrics)return;for(const [name,group] of Object.entries(c9Metrics)){const m=group[$('c9-population').value];const tr=document.createElement('tr');for(const v of [name,m.candidates,c9Pct(m.precision),c9Pct(m.recall),m.exact_positions+'/'+m.positions,m.false_positive,m.false_illegal,m.unknown]){const td=document.createElement('td');td.style.padding='8px';td.textContent=v;tr.append(td)}body.append(tr)}}
async function c9Load(section,button){button.disabled=true;c9Failure=null;$('c9-use').disabled=true;$('c9-status').textContent='Loading recorded '+section+'…';try{const r=await fetch('/cycle9?section='+encodeURIComponent(section));const d=await r.json();if(!r.ok)throw Error(d.error);if(!d.available)throw Error(d.reason);c9Current=d;$('c9-detail').textContent=JSON.stringify(d,null,2);if(section==='summary'){c9Metrics=d.data;c9Render()}if(section==='failures'){$('c9-case').replaceChildren();for(const item of d.data){const option=document.createElement('option');option.value=item.index;option.textContent=item.mode+' · '+item.family+' · '+item.fixture+' '+item.move;$('c9-case').append(option)}$('c9-case').disabled=false;$('c9-proof').disabled=false}$('c9-status').textContent='Recorded '+section+' loaded · '+d.sha256;}catch(e){c9Current=null;$('c9-status').textContent='Error: '+e.message}finally{button.disabled=false}}
for(const [id,section] of [['c9-load','summary'],['c9-calibration','calibration'],['c9-failures','failures'],['c9-performance','performance'],['c9-identity','identity']])$(id).addEventListener('click',()=>c9Load(section,$(id)));
$('c9-population').addEventListener('change',c9Render);
$('c9-case').addEventListener('change',()=>{c9Failure=null;$('c9-use').disabled=true});
$('c9-proof').addEventListener('click',async()=>{const button=$('c9-proof');button.disabled=true;try{const r=await fetch('/cycle9-proof?index='+encodeURIComponent($('c9-case').value));const d=await r.json();if(!r.ok)throw Error(d.error);c9Current=d;c9Failure=d.data;$('c9-detail').textContent=JSON.stringify(d,null,2);$('c9-use').disabled=false;$('c9-status').textContent='Recorded native proof '+d.data.row.proof_id+' · rule and evidence IDs retained.'}catch(e){c9Current=null;c9Failure=null;$('c9-use').disabled=true;$('c9-status').textContent='Error: '+e.message}finally{button.disabled=false}});
$('c9-use').addEventListener('click',()=>{if(!c9Failure)return;const r=c9Failure.row;$('fen').value=r.fen;$('move').value=r.move;$('mode').value=r.mode;$('model').value='C8-default';$('compare-models').checked=false;$('temporal-mode').value='fen-only';$('history').value='{}';$('max-invocations').value=20000;$('form').requestSubmit();$('form').scrollIntoView()});
$('c9-export').addEventListener('click',()=>{if(!c9Current)return;const url=URL.createObjectURL(new Blob([JSON.stringify(c9Current,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='pln-chess-cycle9-research.json';a.click();URL.revokeObjectURL(url)});
'''


def extend(html):
    html=html.replace('</main>',PANEL+'</main>')
    html=html.replace('<details><summary>Runtime, budget, and raw result</summary>',LIVE+'<details><summary>Runtime, budget, and raw result</summary>')
    html=html.replace('function show(c){', "function show(c){$('c9-live').textContent=JSON.stringify(c.research_diagnostics||{available:false,native:false,reason:'No Cycle 9 diagnostic attached'},null,2);")
    html=html.replace("'temporal','promotion']", "'temporal','promotion','c9-live']")
    return html.replace('</script>',SCRIPT+'</script>')
